<?php require_once __DIR__.'/../includes/layout.php';role('superadmin');$rows=db()->query('SELECT u.*,s.name shop FROM users u LEFT JOIN shops s ON s.id=u.shop_id ORDER BY u.id DESC')->fetchAll();start('Users');?><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Shop</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['shop'])?></td></tr><?php endforeach;?></table><?php render_end();
